@pytest.mark.parametrize('scope,version', [(['R'], 'qualified-revision-1'), (['S'], '1')]) def test_scoped_revision_preserves_unrelated_checker_identity(tmp_path, scope, version, monkeypatch): from tests.application.software_project import test_milestone_consumer as fixtures acceptance_type = fixtures.GoalAcceptance def initial_registry(store, project, run, requirements, checkers): return acceptance_type(store, project, run, {**requirements, 'S': {'must': True}}, checkers) monkeypatch.setattr(fixtures, 'GoalAcceptance', initial_registry) old, request, a, workspace, original, decision, proof = fixture(tmp_path) proof['requirement_scope'] = scope decision['qualification_ref'] = put_evidence(a.store, 'p', 'r', proof) revision = bind_checker_revision(a.store, 'p', 'r', 'independent', original, decision) executor = ExternalAcceptanceExecutor(workspace, tmp_path, session_acceptance=a, consumer=original, qualified_revision=revision) result = executor.execute(replace(request, attempt_id='scoped')) assert result.succeeded assert result.outputs['goal_check']['checker_version'] == version assert result.metadata['independent_checker_hash'] == ( revision['checker_hash'] if scope == ['R'] else original['sha256']) a.store.save_result(result) > a.record('g', result, executor_ref='project.acceptance@1')
